def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the solid marker row or column.
    axis = None
    marker = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            axis, marker = 0, r
            break
    if axis is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                axis, marker = 1, c
                break
    if axis is None:
        return out

    # The most common non-marker color is the background.
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (2, background)]
    if not obj:
        return out

    coords = [r if axis == 0 else c for r, c in obj]
    lo, hi = min(coords), max(coords)

    # Move the object adjacent to the marker, then draw an 8-line just
    # beyond the object's far edge.
    if hi < marker:
        shift = marker - 1 - hi
        line_pos = lo + shift - 1
    else:
        shift = marker + 1 - lo
        line_pos = hi + shift + 1

    for r, c in obj:
        out[r][c] = background
    for r, c in obj:
        if axis == 0:
            nr, nc = r + shift, c
        else:
            nr, nc = r, c + shift
        if 0 <= nr < h and 0 <= nc < w:
            out[nr][nc] = grid[r][c]

    if axis == 0 and 0 <= line_pos < h:
        out[line_pos] = [8] * w
    elif axis == 1 and 0 <= line_pos < w:
        for r in range(h):
            out[r][line_pos] = 8

    return out
